_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
# locale -> (decimal, group, code before the number)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True), "pt-BR": (",", ".", True), "de-DE": (",", ".", False),
    "es": (",", ".", False), "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}
_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago", "US/Mountain": "America/Denver",
    "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv", "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo", "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}


def _links() -> dict[str, str]:
    links = dict(_LINKS)
    try:
        import sysconfig
        import os
        import zoneinfo
        for base in list(zoneinfo.TZPATH):
            f = os.path.join(base, "tzdata.zi")
            if os.path.exists(f):
                with open(f) as fh:
                    for ln in fh:
                        parts = ln.split()
                        if len(parts) >= 3 and parts[0] == "L":
                            links.setdefault(parts[2], parts[1])
                break
    except Exception:
        pass
    return links


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if hours == 0 and int(m.group(3) or 0) == 0:
            return "Etc/UTC"
        east = m.group(1) == "+"
        return f"Etc/GMT{'-' if east else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    links = _links()
    seen = 0
    while tz in links and seen < 5:
        tz = links[tz]
        seen += 1
    return tz


def _locale(raw: str) -> str:
    tag = re.split(r"[.@]", raw.strip())[0].replace("_", "-")
    parts = tag.split("-")
    tag = parts[0].lower() + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _LOCALES:
        return tag
    if parts[0].lower() in _LOCALES:
        return parts[0].lower()
    return "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _amount(value: str, currency: str) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-_digits(currency)), rounding=ROUND_HALF_EVEN)


def _group(ints: str, locale: str, sep: str) -> str:
    if locale == "es" and len(ints) == 4:
        return ints
    if locale == "en-IN" and len(ints) > 3:
        head, tail = ints[:-3], ints[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return sep.join(pieces + [tail])
    pieces = []
    while len(ints) > 3:
        pieces.insert(0, ints[-3:])
        ints = ints[:-3]
    return sep.join([ints] + pieces)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    n = _digits(currency)
    neg = value < 0
    q = f"{abs(value):.{n}f}"
    ints, _, frac = q.partition(".")
    num = _group(ints, locale, grp) + (dec + frac if n else "")
    if neg:
        num = "-" + num
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    after = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": after.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], cur) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, cur, locale)))
    total = sum((line.net for line in lines), Decimal(0))
    return Statement(merchant.id, cur, tuple(lines), total, _text(total, cur, locale))
'''
